/*
 * Vendor the required element-identifier icons (spec §2 icon table) from the
 * offline @iconify-json collections into ONE small TS module, so the editor:
 *   - keeps exact iconify identifiers (codicon:screen-full, …),
 *   - ships only ~8 glyph bodies instead of multi-MB collections,
 *   - stays offline (no iconify API at runtime),
 *   - and tsc/webpack never choke on 40k-icon JSON files.
 *
 * Run: node scripts/vendor-icons.mjs   (after npm install — collections are devDeps)
 * Output: src/components/builder/icons/vendor.ts (generated; do not edit).
 */
import { readFileSync, writeFileSync } from 'node:fs'
import { resolve } from 'node:path'

const ROOT = resolve(import.meta.dirname, '..')

/** The required identifier set (spec §2) — real collection prefixes. */
const WANTED = {
  codicon: ['screen-full'],
  'ant-design': ['mobile-filled'],
  tabler: ['hand-click'],
  'akar-icons': ['image'],
  andrsrxn: ['text-case-sensitive'],
  reicon: ['text-input-focus'],
  f7: ['square-stack-3d-down-right'],
  iconmind: ['navbar-duotone-thin']
}

const collections = []
for (const [prefix, names] of Object.entries(WANTED)) {
  const full = JSON.parse(readFileSync(resolve(ROOT, 'node_modules/@iconify-json', prefix, 'icons.json'), 'utf8'))
  const icons = {}
  const aliases = {}
  for (const name of names) {
    if (full.icons?.[name]) {
      icons[name] = full.icons[name]
      continue
    }
    // Resolve through the alias table (and copy the alias entry so the
    // original identifier keeps working offline).
    const alias = full.aliases?.[name]
    if (alias && full.icons?.[alias.parent]) {
      aliases[name] = alias
      icons[alias.parent] = full.icons[alias.parent]
      continue
    }
    throw new Error(`Icon ${prefix}:${name} not found in collection`)
  }
  collections.push({
    prefix,
    width: full.width,
    height: full.height,
    lastModified: full.lastModified,
    icons,
    ...(Object.keys(aliases).length ? { aliases } : {})
  })
}

const out = `/*
 * GENERATED by scripts/vendor-icons.mjs — do not edit by hand.
 *
 * The required element-identifier icons (spec §2 icon table), vendored from
 * the offline @iconify-json/* collections (devDependencies) so the client
 * bundle carries only these glyph bodies. Source collections remain MIT-
 * licensed per their upstream projects; identifiers are preserved verbatim:
 *   codicon:screen-full · ant-design:mobile-filled · tabler:hand-click ·
 *   akar-icons:image · andrsrxn:text-case-sensitive · reicon:text-input-focus ·
 *   f7:square-stack-3d-down-right · iconmind:navbar-duotone-thin
 */
import type { IconifyJSON } from '@iconify/react'

export const VENDORED_COLLECTIONS: IconifyJSON[] = ${JSON.stringify(collections, null, 2)}
`

writeFileSync(resolve(ROOT, 'src/components/builder/icons/vendor.ts'), out)
console.log(
  'Vendored',
  collections.reduce((n, c) => n + Object.keys(c.icons).length, 0),
  'icons from',
  collections.length,
  'collections →',
  'src/components/builder/icons/vendor.ts'
)
